use std::collections::BTreeMap;
use std::fs;
use std::process;

mod abi;
mod encoder;
mod decoder;
mod types;

use clap::{Arg, Command};
use serde_json::json;

fn main() {
    let app = Command::new("executable")
        .version("ethabi-cli 18.0.0")
        .about("Ethereum ABI coder")
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(
            Command::new("encode")
                .about("Encode ABI call")
                .subcommand_required(true)
                .arg_required_else_help(true)
                .subcommand(
                    Command::new("function")
                        .about("Load function from JSON ABI file")
                        .arg(Arg::new("abi-path").required(true).index(1))
                        .arg(Arg::new("function-name-or-signature").required(true).index(2))
                        .arg(Arg::new("params")
                            .short('p')
                            .long("params")
                            .num_args(1..)
                            .action(clap::ArgAction::Append))
                        .arg(Arg::new("lenient")
                            .short('l')
                            .long("lenient")
                            .help("Allow short representation of input params")
                            .action(clap::ArgAction::SetTrue))
                )
                .subcommand(
                    Command::new("params")
                        .about("Specify types of input params inline")
                        .arg(Arg::new("type-or-param")
                            .short('v')
                            .long("type-or-param")
                            .num_args(2)
                            .action(clap::ArgAction::Append))
                        .arg(Arg::new("lenient")
                            .short('l')
                            .long("lenient")
                            .help("Allow short representation of input params (numbers are in decimal form)")
                            .action(clap::ArgAction::SetTrue))
                )
        )
        .subcommand(
            Command::new("decode")
                .about("Decode ABI call result")
                .subcommand_required(true)
                .arg_required_else_help(true)
                .subcommand(
                    Command::new("function")
                        .about("Load function from JSON ABI file")
                        .arg(Arg::new("abi-path").required(true).index(1))
                        .arg(Arg::new("function-name-or-signature").required(true).index(2))
                        .arg(Arg::new("data").required(true).index(3))
                )
                .subcommand(
                    Command::new("params")
                        .about("Specify types of input params inline")
                        .arg(Arg::new("type")
                            .short('t')
                            .long("type")
                            .num_args(1)
                            .action(clap::ArgAction::Append))
                        .arg(Arg::new("data").required(true).index(1))
                )
                .subcommand(
                    Command::new("log")
                        .about("Decode event log")
                        .arg(Arg::new("abi-path").required(true).index(1))
                        .arg(Arg::new("event-name-or-signature").required(true).index(2))
                        .arg(Arg::new("data").required(true).index(3))
                        .arg(Arg::new("topic")
                            .short('l')
                            .long("topic")
                            .num_args(1)
                            .action(clap::ArgAction::Append))
                )
        );

    let matches = app.get_matches();

    match matches.subcommand() {
        Some(("encode", encode_matches)) => {
            match encode_matches.subcommand() {
                Some(("function", func_matches)) => {
                    let abi_path = func_matches.get_one::<String>("abi-path").unwrap();
                    let func_sig = func_matches.get_one::<String>("function-name-or-signature").unwrap();
                    let params: Vec<String> = func_matches
                        .get_many::<String>("params")
                        .map(|vals| vals.map(|v| v.to_string()).collect())
                        .unwrap_or_default();
                    let lenient = func_matches.get_flag("lenient");

                    if let Err(e) = encode_function(abi_path, func_sig, params, lenient) {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
                Some(("params", param_matches)) => {
                    let type_param_pairs: Vec<Vec<String>> = param_matches
                        .get_many::<Vec<String>>("type-or-param")
                        .map(|vals| vals.map(|v| v.clone()).collect())
                        .unwrap_or_default();
                    let lenient = param_matches.get_flag("lenient");

                    if let Err(e) = encode_params(type_param_pairs, lenient) {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
                _ => {}
            }
        }
        Some(("decode", decode_matches)) => {
            match decode_matches.subcommand() {
                Some(("function", func_matches)) => {
                    let abi_path = func_matches.get_one::<String>("abi-path").unwrap();
                    let func_sig = func_matches.get_one::<String>("function-name-or-signature").unwrap();
                    let data = func_matches.get_one::<String>("data").unwrap();

                    if let Err(e) = decode_function(abi_path, func_sig, data) {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
                Some(("params", param_matches)) => {
                    let types: Vec<String> = param_matches
                        .get_many::<String>("type")
                        .map(|vals| vals.map(|v| v.to_string()).collect())
                        .unwrap_or_default();
                    let data = param_matches.get_one::<String>("data").unwrap();

                    if let Err(e) = decode_params(types, data) {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
                Some(("log", log_matches)) => {
                    let abi_path = log_matches.get_one::<String>("abi-path").unwrap();
                    let event_sig = log_matches.get_one::<String>("event-name-or-signature").unwrap();
                    let data = log_matches.get_one::<String>("data").unwrap();
                    let topics: Vec<String> = log_matches
                        .get_many::<String>("topic")
                        .map(|vals| vals.map(|v| v.to_string()).collect())
                        .unwrap_or_default();

                    if let Err(e) = decode_log(abi_path, event_sig, &topics, data) {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
                _ => {}
            }
        }
        _ => {}
    }
}

fn encode_function(abi_path: &str, func_sig: &str, params: Vec<String>, lenient: bool) -> Result<(), String> {
    let abi_content = fs::read_to_string(abi_path)
        .map_err(|e| format!("Failed to read ABI file: {}", e))?;

    let abi_json: serde_json::Value = serde_json::from_str(&abi_content)
        .map_err(|e| format!("Invalid JSON in ABI file: {}", e))?;

    let functions = abi::extract_functions(&abi_json)?;
    let func = abi::find_function(&functions, func_sig)?;

    let encoded = encoder::encode_function(&func, &params, lenient)?;
    println!("{}", encoded);
    Ok(())
}

fn encode_params(type_param_pairs: Vec<Vec<String>>, lenient: bool) -> Result<(), String> {
    let mut encoded_parts = Vec::new();

    for pair in type_param_pairs {
        if pair.len() != 2 {
            return Err("Each -v option requires both type and value".to_string());
        }
        let typ = &pair[0];
        let param = &pair[1];
        let encoded = encoder::encode_param(typ, param, lenient)?;
        encoded_parts.push(encoded);
    }

    // Concatenate all encoded parts with dynamic offsets adjusted
    let result = encoder::combine_encoded_params(encoded_parts)?;
    println!("{}", result);
    Ok(())
}

fn decode_function(abi_path: &str, func_sig: &str, data: &str) -> Result<(), String> {
    let abi_content = fs::read_to_string(abi_path)
        .map_err(|e| format!("Failed to read ABI file: {}", e))?;

    let abi_json: serde_json::Value = serde_json::from_str(&abi_content)
        .map_err(|e| format!("Invalid JSON in ABI file: {}", e))?;

    let functions = abi::extract_functions(&abi_json)?;
    let func = abi::find_function(&functions, func_sig)?;

    let outputs = &func.get("outputs")
        .and_then(|v| v.as_array())
        .ok_or("Function has no outputs")?;

    decoder::decode_function(outputs, data)?;
    Ok(())
}

fn decode_params(types: Vec<String>, data: &str) -> Result<(), String> {
    decoder::decode_params(&types, data)?;
    Ok(())
}

fn decode_log(abi_path: &str, event_sig: &str, topics: &[String], data: &str) -> Result<(), String> {
    let abi_content = fs::read_to_string(abi_path)
        .map_err(|e| format!("Failed to read ABI file: {}", e))?;

    let abi_json: serde_json::Value = serde_json::from_str(&abi_content)
        .map_err(|e| format!("Invalid JSON in ABI file: {}", e))?;

    let events = abi::extract_events(&abi_json)?;
    let event = abi::find_event(&events, event_sig)?;

    decoder::decode_log(&event, topics, data)?;
    Ok(())
}
