use std::str::FromStr;

pub fn parse_type(type_str: &str) -> Result<AbiType, String> {
    let type_str = type_str.trim();

    if type_str == "bool" {
        Ok(AbiType::Bool)
    } else if type_str == "address" {
        Ok(AbiType::Address)
    } else if type_str == "string" {
        Ok(AbiType::String)
    } else if type_str == "bytes" {
        Ok(AbiType::Bytes)
    } else if type_str.starts_with("bytes") {
        let num_str = &type_str[5..];
        let size: usize = num_str.parse()
            .map_err(|_| format!("Invalid bytes type: {}", type_str))?;
        if size < 1 || size > 32 {
            return Err(format!("bytes size must be between 1 and 32"));
        }
        Ok(AbiType::FixedBytes(size))
    } else if type_str.starts_with("uint") {
        let num_str = if type_str == "uint" {
            "256"
        } else {
            &type_str[4..]
        };
        let bits: usize = num_str.parse()
            .map_err(|_| format!("Invalid uint type: {}", type_str))?;
        if bits % 8 != 0 || bits < 8 || bits > 256 {
            return Err(format!("uint size must be a multiple of 8 between 8 and 256"));
        }
        Ok(AbiType::Uint(bits))
    } else if type_str.starts_with("int") {
        let num_str = if type_str == "int" {
            "256"
        } else {
            &type_str[3..]
        };
        let bits: usize = num_str.parse()
            .map_err(|_| format!("Invalid int type: {}", type_str))?;
        if bits % 8 != 0 || bits < 8 || bits > 256 {
            return Err(format!("int size must be a multiple of 8 between 8 and 256"));
        }
        Ok(AbiType::Int(bits))
    } else if type_str.ends_with("[]") {
        let base_type = &type_str[..type_str.len() - 2];
        let inner = parse_type(base_type)?;
        Ok(AbiType::Array(Box::new(inner)))
    } else if type_str.contains('[') && type_str.contains(']') {
        // Fixed-size array
        let bracket_idx = type_str.rfind('[').unwrap();
        let base_type = &type_str[..bracket_idx];
        let size_str = &type_str[bracket_idx + 1..type_str.len() - 1];
        let size: usize = size_str.parse()
            .map_err(|_| format!("Invalid array size: {}", size_str))?;
        let inner = parse_type(base_type)?;
        Ok(AbiType::FixedArray(Box::new(inner), size))
    } else {
        Err(format!("Unknown type: {}", type_str))
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum AbiType {
    Bool,
    Address,
    String,
    Bytes,
    FixedBytes(usize),
    Uint(usize),
    Int(usize),
    Array(Box<AbiType>),
    FixedArray(Box<AbiType>, usize),
}

impl AbiType {
    pub fn is_dynamic(&self) -> bool {
        match self {
            AbiType::String | AbiType::Bytes | AbiType::Array(_) => true,
            AbiType::FixedArray(inner, _) => inner.is_dynamic(),
            _ => false,
        }
    }
}
