use serde_json::Value;
use crate::types::{parse_type, AbiType};
use crate::abi;

pub fn encode_function(func: &Value, params: &[String], lenient: bool) -> Result<String, String> {
    // Get function selector (first 4 bytes of keccak256 hash)
    let selector = abi::compute_function_selector(func)?;

    let inputs = func.get("inputs")
        .and_then(|i| i.as_array())
        .unwrap_or(&vec![]);

    if inputs.len() != params.len() {
        return Err(format!("Expected {} parameters, got {}", inputs.len(), params.len()));
    }

    let mut encoded_data = vec![];
    let mut dynamic_parts = vec![];
    let mut offset = 32 * (inputs.iter().filter(|i| {
        let typ = i.get("type").and_then(|t| t.as_str()).unwrap_or("");
        parse_type(typ).map(|t| t.is_dynamic()).unwrap_or(false)
    }).count());

    for (i, input) in inputs.iter().enumerate() {
        let typ_str = input.get("type")
            .and_then(|t| t.as_str())
            .ok_or("Input type not specified")?;
        let typ = parse_type(typ_str)?;

        let encoded = encode_value(&typ, &params[i], lenient)?;

        if typ.is_dynamic() {
            // Store offset and the actual data separately
            encoded_data.extend_from_slice(&pad_left(&encode_uint256(offset as u64), 32));
            dynamic_parts.push((offset, encoded.clone()));
            offset += encoded.len();
        } else {
            encoded_data.extend_from_slice(&encoded);
        }
    }

    // Append dynamic parts
    for (_, data) in dynamic_parts {
        encoded_data.extend_from_slice(&data);
    }

    let mut result = String::new();
    result.push_str(&hex::encode(&selector));
    result.push_str(&hex::encode(&encoded_data));

    Ok(result)
}

pub fn encode_param(typ_str: &str, param: &str, lenient: bool) -> Result<Vec<u8>, String> {
    let typ = parse_type(typ_str)?;
    encode_value(&typ, param, lenient)
}

pub fn encode_value(typ: &AbiType, value: &str, lenient: bool) -> Result<Vec<u8>, String> {
    match typ {
        AbiType::Bool => {
            let b = match value {
                "1" | "true" | "True" => true,
                "0" | "false" | "False" => false,
                _ => return Err(format!("Invalid bool value: {}", value))
            };
            Ok(pad_left(&encode_bool(b), 32))
        }
        AbiType::Address => {
            // Address must be 20 bytes
            let addr = if value.starts_with("0x") {
                &value[2..]
            } else {
                value
            };

            if addr.len() != 40 {
                return Err(format!("Invalid address length: {}", value));
            }

            let bytes = hex::decode(addr)
                .map_err(|_| format!("Invalid address hex: {}", value))?;

            Ok(pad_left(&bytes, 32))
        }
        AbiType::String => {
            let string_bytes = value.as_bytes();
            let mut result = vec![];
            result.extend_from_slice(&pad_left(&encode_uint256(string_bytes.len() as u64), 32));
            result.extend_from_slice(&pad_right(string_bytes, (string_bytes.len() + 31) / 32 * 32));
            Ok(result)
        }
        AbiType::Bytes => {
            let bytes_data = if value.starts_with("0x") {
                hex::decode(&value[2..])
            } else {
                hex::decode(value)
            }.map_err(|_| format!("Invalid hex value: {}", value))?;

            let mut result = vec![];
            result.extend_from_slice(&pad_left(&encode_uint256(bytes_data.len() as u64), 32));
            result.extend_from_slice(&pad_right(&bytes_data, (bytes_data.len() + 31) / 32 * 32));
            Ok(result)
        }
        AbiType::FixedBytes(size) => {
            let bytes_data = if value.starts_with("0x") {
                hex::decode(&value[2..])
            } else {
                hex::decode(value)
            }.map_err(|_| format!("Invalid hex value: {}", value))?;

            if bytes_data.len() != *size {
                return Err(format!("bytes{} expects exactly {} bytes, got {}", size, size, bytes_data.len()));
            }

            Ok(pad_right(&bytes_data, 32))
        }
        AbiType::Uint(bits) => {
            let num = if lenient {
                // Try to parse as decimal first
                value.parse::<u64>()
                    .map(|n| n as u128)
                    .or_else(|_| {
                        // Fall back to hex
                        if value.starts_with("0x") {
                            u128::from_str_radix(&value[2..], 16)
                        } else {
                            u128::from_str_radix(value, 16)
                        }
                    })
                    .map_err(|_| format!("Invalid uint value: {}", value))?
            } else {
                // Parse as hex
                let hex_str = if value.starts_with("0x") {
                    &value[2..]
                } else {
                    value
                };

                if hex_str.len() % 2 != 0 {
                    return Err("Hex parsing error: Odd number of digits".to_string());
                }

                u128::from_str_radix(hex_str, 16)
                    .map_err(|_| format!("Invalid hex value: {}", value))?
            };

            Ok(pad_left(&encode_uint(num, bits / 8), 32))
        }
