    let mut result = vec![0u8; *bytes];
    let mut n = num;
    for i in (0..*bytes).rev() {
        result[i] = (n & 0xFF) as u8;
        n >>= 8;
    }
    result
}

pub fn encode_uint256(num: u64) -> Vec<u8> {
    let mut result = vec![0u8; 32];
    let mut n = num;
    for i in (0..32).rev() {
        result[i] = (n & 0xFF) as u8;
        n >>= 8;
    }
    result
}

pub fn pad_left(data: &[u8], len: usize) -> Vec<u8> {
    if data.len() >= len {
        data.to_vec()
    } else {
        let mut result = vec![0u8; len - data.len()];
        result.extend_from_slice(data);
        result
    }
}

pub fn pad_right(data: &[u8], len: usize) -> Vec<u8> {
    if data.len() >= len {
        data.to_vec()
    } else {
        let mut result = data.to_vec();
        result.resize(len, 0);
