    for part in &parts {
        all_data.extend_from_slice(part);
    }

    for byte in all_data {
        result.push_str(&format!("{:02x}", byte));
    }

    Ok(result)
}

// Hex encoding helper
mod hex {
    pub fn encode(bytes: &[u8]) -> String {
        bytes.iter()
            .map(|b| format!("{:02x}", b))
            .collect()
    }

    pub fn decode(s: &str) -> Result<Vec<u8>, String> {
        if s.len() % 2 != 0 {
