pub fn decode_log(event: &Value, topics: &[String], data: &str) -> Result<(), String> {
    let hex_data = if data.starts_with("0x") {
        &data[2..]
    } else {
        data
    };

    let bytes = hex_to_bytes(hex_data)?;

    let inputs = event.get("inputs")
        .and_then(|i| i.as_array())
        .unwrap_or(&vec![]);

    let mut indexed_count = 0;
    let mut topic_idx = 0;
    let mut data_offset = 0;

    for input in inputs {
        let name = input.get("name")
            .and_then(|n| n.as_str())
            .unwrap_or("");

        let typ_str = input.get("type")
            .and_then(|t| t.as_str())
            .ok_or("Input type not specified")?;
        let typ = parse_type(typ_str)?;

        let indexed = input.get("indexed")
            .and_then(|b| b.as_bool())
            .unwrap_or(false);

        if indexed {
            // Read from topics
            if topic_idx >= topics.len() {
                return Err(format!("Not enough topics for indexed parameter {}", name));
            }
            let topic_hex = if topics[topic_idx].starts_with("0x") {
                &topics[topic_idx][2..]
            } else {
                &topics[topic_idx]
            };
            let topic_bytes = hex_to_bytes(topic_hex)?;

