            // We just show the hash
            let decoded = format_bytes(&topic_bytes);
            println!("{} {}", name, decoded);

            topic_idx += 1;
        } else {
            // Read from data
            let (decoded, new_offset) = decode_value(&typ, &bytes, data_offset)?;
            println!("{} {}", name, decoded);
            data_offset = new_offset;
        }
    }

    Ok(())
