fn decode_value(typ: &AbiType, data: &[u8], offset: usize) -> Result<(String, usize), String> {
    match typ {
        AbiType::Bool => {
            let value = read_uint(data, offset, 32)?;
            let decoded = if value == 1 { "true".to_string() } else { "false".to_string() };
            Ok((decoded, offset + 32))
        }
        AbiType::Address => {
            let addr_bytes = &data[offset + 12..offset + 32];
            let decoded = format_bytes(addr_bytes);
            Ok((decoded, offset + 32))
        }
        AbiType::String => {
            let offset_value = read_uint(data, offset, 32)?;
            let length = read_uint(data, offset_value as usize, 32)?;
            let start = offset_value as usize + 32;
            let end = start + length as usize;
            if end > data.len() {
                return Err("String data out of bounds".to_string());
            }
            let string_data = &data[start..end];
            let decoded = String::from_utf8(string_data.to_vec())
                .map_err(|_| "Invalid UTF-8 in string".to_string())?;
            Ok((decoded, offset + 32))
        }
        AbiType::Bytes => {
            let offset_value = read_uint(data, offset, 32)?;
            let length = read_uint(data, offset_value as usize, 32)?;
            let start = offset_value as usize + 32;
            let end = start + length as usize;
            if end > data.len() {
                return Err("Bytes data out of bounds".to_string());
            }
            let bytes_data = &data[start..end];
            let decoded = format_bytes(bytes_data);
            Ok((decoded, offset + 32))
        }
        AbiType::FixedBytes(size) => {
            let bytes_data = &data[offset..offset + 32];
            let decoded = format_bytes(&bytes_data[..*size]);
            Ok((decoded, offset + 32))
        }
        AbiType::Uint(_) => {
            let value = read_uint(data, offset, 32)?;
            let decoded = format!("{}", value);
            Ok((decoded, offset + 32))
        }
        AbiType::Int(_) => {
            let value = read_int(data, offset, 32)?;
            let decoded = format!("{}", value);
            Ok((decoded, offset + 32))
        }
        _ => Err(format!("Unsupported type for decoding: {:?}", typ))
    }
}

fn read_uint(data: &[u8], offset: usize, bytes: usize) -> Result<u64, String> {
    if offset + bytes > data.len() {
        return Err("Data out of bounds".to_string());
    }

    let mut result: u64 = 0;
    for i in 0..bytes {
        result = (result << 8) | (data[offset + i] as u64);
    }
    Ok(result)
}

fn read_int(data: &[u8], offset: usize, bytes: usize) -> Result<i64, String> {
    if offset + bytes > data.len() {
        return Err("Data out of bounds".to_string());
    }

    let mut result: i64 = 0;
    for i in 0..bytes {
        result = (result << 8) | (data[offset + i] as i64);
    }

    // Check sign bit
    if data[offset] & 0x80 != 0 {
        // Negative number - need to do two's complement
        result = -(((1i64 << (bytes as u64 * 8)) - result) as i64);
    }

    Ok(result)
}

fn hex_to_bytes(hex: &str) -> Result<Vec<u8>, String> {
    if hex.len() % 2 != 0 {
        return Err("Invalid character 'x' at position 1".to_string());
    }

    let mut result = vec![];
    for i in (0..hex.len()).step_by(2) {
        let byte_str = &hex[i..i+2];
        let byte = u8::from_str_radix(byte_str, 16)
            .map_err(|_| format!("Invalid hex character: {}", byte_str))?;
        result.push(byte);
    }
    Ok(result)
}

fn format_bytes(bytes: &[u8]) -> String {
    bytes.iter()
        .map(|b| format!("{:02x}", b))
        .collect()
}
