use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

impl Value {
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::String(s) => Some(s),
            _ => None,
        }
    }

    pub fn as_array(&self) -> Option<&Vec<Value>> {
        match self {
            Value::Array(arr) => Some(arr),
            _ => None,
        }
    }

    pub fn as_object(&self) -> Option<&BTreeMap<String, Value>> {
        match self {
            Value::Object(obj) => Some(obj),
            _ => None,
        }
    }

    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            _ => None,
        }
    }

    pub fn as_u64(&self) -> Option<u64> {
        match self {
            Value::Number(n) => Some(*n as u64),
            _ => None,
        }
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Object(obj) => obj.get(key),
            _ => None,
        }
    }
}

pub fn parse(input: &str) -> Result<Value, String> {
    let mut parser = Parser::new(input);
    parser.parse_value()
}

struct Parser {
    input: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_whitespace();

        if self.pos >= self.input.len() {
            return Err("Unexpected end of input".to_string());
        }

        match self.input[self.pos] {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            '-' | '0'..='9' => self.parse_number(),
            _ => Err(format!("Unexpected character: {}", self.input[self.pos])),
        }
    }

    fn parse_object(&mut self) -> Result<Value, String> {
        self.pos += 1; // consume '{'
        self.skip_whitespace();

        let mut obj = BTreeMap::new();

        if self.pos < self.input.len() && self.input[self.pos] == '}' {
            self.pos += 1;
            return Ok(Value::Object(obj));
        }

        loop {
            self.skip_whitespace();

            // Parse key
            if self.input[self.pos] != '"' {
                return Err("Expected string key in object".to_string());
            }
            let key = match self.parse_string()? {
                Value::String(s) => s,
                _ => return Err("Invalid key".to_string()),
            };

            self.skip_whitespace();
            if self.pos >= self.input.len() || self.input[self.pos] != ':' {
                return Err("Expected ':' after key".to_string());
            }
            self.pos += 1;

            // Parse value
            let value = self.parse_value()?;
            obj.insert(key, value);

            self.skip_whitespace();
            if self.pos >= self.input.len() {
                return Err("Unexpected end of input in object".to_string());
            }

            match self.input[self.pos] {
                ',' => {
                    self.pos += 1;
                }
                '}' => {
                    self.pos += 1;
                    break;
                }
                _ => return Err("Expected ',' or '}' in object".to_string()),
            }
        }

        Ok(Value::Object(obj))
    }

    fn parse_array(&mut self) -> Result<Value, String> {
        self.pos += 1; // consume '['
        self.skip_whitespace();

        let mut arr = vec![];

        if self.pos < self.input.len() && self.input[self.pos] == ']' {
            self.pos += 1;
            return Ok(Value::Array(arr));
        }

        loop {
            arr.push(self.parse_value()?);

            self.skip_whitespace();
            if self.pos >= self.input.len() {
                return Err("Unexpected end of input in array".to_string());
            }

            match self.input[self.pos] {
                ',' => {
                    self.pos += 1;
                }
                ']' => {
                    self.pos += 1;
                    break;
                }
                _ => return Err("Expected ',' or ']' in array".to_string()),
            }
        }

        Ok(Value::Array(arr))
    }

    fn parse_string(&mut self) -> Result<Value, String> {
        self.pos += 1; // consume '"'
        let mut result = String::new();

        while self.pos < self.input.len() {
            match self.input[self.pos] {
                '"' => {
                    self.pos += 1;
                    return Ok(Value::String(result));
                }
                '\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() {
                        return Err("Unexpected end of string".to_string());
                    }
                    match self.input[self.pos] {
                        '"' => result.push('"'),
                        '\\' => result.push('\\'),
                        '/' => result.push('/'),
                        'b' => result.push('\u{0008}'),
                        'f' => result.push('\u{000c}'),
                        'n' => result.push('\n'),
                        'r' => result.push('\r'),
                        't' => result.push('\t'),
                        'u' => {
                            // Unicode escape
                            self.pos += 1;
                            let mut code = String::new();
                            for _ in 0..4 {
                                if self.pos >= self.input.len() {
                                    return Err("Invalid unicode escape".to_string());
                                }
                                code.push(self.input[self.pos]);
                                self.pos += 1;
                            }
                            self.pos -= 1;
                            let code_point = u32::from_str_radix(&code, 16)
                                .map_err(|_| "Invalid unicode escape".to_string())?;
                            if let Some(c) = char::from_u32(code_point) {
                                result.push(c);
                            }
                        }
                        _ => return Err(format!("Invalid escape sequence: \\{}", self.input[self.pos])),
                    }
                    self.pos += 1;
                }
                c => {
                    result.push(c);
                    self.pos += 1;
                }
            }
        }

        Err("Unterminated string".to_string())
    }

    fn parse_number(&mut self) -> Result<Value, String> {
        let start = self.pos;

        if self.input[self.pos] == '-' {
            self.pos += 1;
        }

        if self.pos >= self.input.len() || !self.input[self.pos].is_ascii_digit() {
            return Err("Invalid number".to_string());
        }

        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
            self.pos += 1;
        }

        if self.pos < self.input.len() && self.input[self.pos] == '.' {
            self.pos += 1;
            if self.pos >= self.input.len() || !self.input[self.pos].is_ascii_digit() {
                return Err("Invalid number".to_string());
            }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }

        if self.pos < self.input.len() && (self.input[self.pos] == 'e' || self.input[self.pos] == 'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == '+' || self.input[self.pos] == '-') {
                self.pos += 1;
            }
            if self.pos >= self.input.len() || !self.input[self.pos].is_ascii_digit() {
                return Err("Invalid number".to_string());
            }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }

        let num_str: String = self.input[start..self.pos].iter().collect();
        let num = num_str.parse::<f64>()
            .map_err(|_| "Invalid number".to_string())?;

        Ok(Value::Number(num))
    }

    fn parse_bool(&mut self) -> Result<Value, String> {
