use crate::types::{parse_type, AbiType};
use crate::abi;

pub fn encode_function(func: &Value, params: Vec<String>, lenient: bool) -> Result<String, String> {
    // Get function selector
    let selector = abi::compute_function_selector(func)?;

    let inputs = func.get("inputs")
        .and_then(|i| i.as_array())
        .unwrap_or(&vec![]);

    if inputs.len() != params.len() {
        return Err(format!("Expected {} parameters, got {}", inputs.len(), params.len()));
    }

    let mut encoded_data = vec![];
    let mut dynamic_parts = vec![];

    // First pass: count dynamic params to calculate offset
    let mut static_size = 0;
    for input in inputs.iter() {
        let typ_str = input.get("type")
            .and_then(|t| t.as_str())
            .ok_or("Input type not specified")?;
        let typ = parse_type(typ_str)?;

        if typ.is_dynamic() {
            static_size += 32; // offset takes 32 bytes
        } else {
            static_size += 32; // all static values are 32 bytes aligned
        }
    }

    // Second pass: encode params
    let mut current_dynamic_offset = static_size;
    for (i, input) in inputs.iter().enumerate() {
        let typ_str = input.get("type")
            .and_then(|t| t.as_str())
            .ok_or("Input type not specified")?;
        let typ = parse_type(typ_str)?;

        let encoded = encode_value(&typ, &params[i], lenient)?;

        if typ.is_dynamic() {
            // Store offset
            encoded_data.extend_from_slice(&pad_left(&encode_uint256(current_dynamic_offset as u64), 32));
            dynamic_parts.push((current_dynamic_offset, encoded.clone()));
            current_dynamic_offset += encoded.len();
        } else {
            encoded_data.extend_from_slice(&encoded);
        }
    }

    // Append dynamic parts
    for (_, data) in dynamic_parts {
        encoded_data.extend_from_slice(&data);
    }

    let mut result = String::new();
    result.push_str(&encode_hex(&selector));
    result.push_str(&encode_hex(&encoded_data));

    Ok(result)
}

pub fn encode_params_direct(type_params: Vec<(String, String)>, lenient: bool) -> Result<String, String> {
