                let hex_str = if value.starts_with("0x") {
                    &value[2..]
                } else {
                    value
                };

                if hex_str.len() % 2 != 0 {
                    return Err("Hex parsing error: Odd number of digits".to_string());
                }

                u128::from_str_radix(hex_str, 16)
                    .map_err(|_| format!("Invalid hex value: {}", value))?
            };

            Ok(pad_left(&encode_uint(num, bits / 8), 32))
        }
        AbiType::Int(_bits) => {
            let num = if lenient {
                value.parse::<i64>()
                    .map(|n| n as u128)
                    .or_else(|_| {
                        if value.starts_with("0x") {
                            u128::from_str_radix(&value[2..], 16)
                        } else {
                            u128::from_str_radix(value, 16)
                        }
                    })
                    .map_err(|_| format!("Invalid int value: {}", value))?
            } else {
                let hex_str = if value.starts_with("0x") {
                    &value[2..]
                } else {
                    value
                };

                if hex_str.len() % 2 != 0 {
                    return Err("Hex parsing error: Odd number of digits".to_string());
                }

                u128::from_str_radix(hex_str, 16)
                    .map_err(|_| format!("Invalid hex value: {}", value))?
            };

            Ok(pad_left(&encode_uint(num, 32), 32))
        }
        _ => Err(format!("Unsupported type for encoding: {:?}", typ))
    }
}

fn encode_uint(num: u128, bytes: usize) -> Vec<u8> {
    let mut result = vec![0u8; bytes];
    let mut n = num;
    for i in (0..bytes).rev() {
        result[i] = (n & 0xFF) as u8;
        n >>= 8;
    }
    result
}

fn encode_uint256(num: u64) -> Vec<u8> {
    let mut result = vec![0u8; 32];
    let mut n = num;
    for i in (0..32).rev() {
        result[i] = (n & 0xFF) as u8;
        n >>= 8;
    }
    result
}

fn pad_left(data: &[u8], len: usize) -> Vec<u8> {
    if data.len() >= len {
        data.to_vec()
    } else {
        let mut result = vec![0u8; len - data.len()];
        result.extend_from_slice(data);
        result
    }
}

fn pad_right(data: &[u8], len: usize) -> Vec<u8> {
    if data.len() >= len {
        data.to_vec()
    } else {
        let mut result = data.to_vec();
        result.resize(len, 0);
        result
    }
}

fn encode_hex(bytes: &[u8]) -> String {
    bytes.iter()
        .map(|b| format!("{:02x}", b))
        .collect()
}

fn decode_hex(s: &str) -> Result<Vec<u8>, String> {
    if s.len() % 2 != 0 {
        return Err("Hex parsing error: Odd number of digits".to_string());
    }

    let mut result = vec![];
    for i in (0..s.len()).step_by(2) {
        let byte_str = &s[i..i+2];
        let byte = u8::from_str_radix(byte_str, 16)
            .map_err(|_| "Invalid hex character".to_string())?;
        result.push(byte);
    }
    Ok(result)
}
