        match self {
            AbiType::String | AbiType::Bytes | AbiType::Array(_) => true,
            AbiType::FixedArray(inner, _) => inner.is_dynamic(),
            _ => false,
        }
    }
}

pub fn parse_type(type_str: &str) -> Result<AbiType, String> {
    let type_str = type_str.trim();

    if type_str == "bool" {
