        let inner = parse_type(base_type)?;
        Ok(AbiType::Array(Box::new(inner)))
    } else if type_str.contains('[') && type_str.contains(']') {
        // Fixed-size array
        let bracket_idx = type_str.rfind('[').unwrap();
        let base_type = &type_str[..bracket_idx];
