use std::fs;
use crate::json::{self, Value};
use crate::encoder;
use crate::decoder;

pub fn load_and_encode_function(abi_path: &str, func_sig: &str, params: Vec<String>, lenient: bool) -> Result<String, String> {
    let content = fs::read_to_string(abi_path)
        .map_err(|e| format!("Failed to read ABI file: {}", e))?;

    let abi = json::parse(&content)
        .map_err(|e| format!("Invalid JSON in ABI file: {}", e))?;

    let func = find_function(&abi, func_sig)?;
    encoder::encode_function(&func, params, lenient)
}

pub fn load_and_decode_function(abi_path: &str, func_sig: &str, data: &str) -> Result<(), String> {
    let content = fs::read_to_string(abi_path)
        .map_err(|e| format!("Failed to read ABI file: {}", e))?;

    let abi = json::parse(&content)
        .map_err(|e| format!("Invalid JSON in ABI file: {}", e))?;

    let func = find_function(&abi, func_sig)?;
    decoder::decode_function(&func, data)
}

pub fn load_and_decode_log(abi_path: &str, event_sig: &str, topics: &[String], data: &str) -> Result<(), String> {
    let content = fs::read_to_string(abi_path)
        .map_err(|e| format!("Failed to read ABI file: {}", e))?;

    let abi = json::parse(&content)
        .map_err(|e| format!("Invalid JSON in ABI file: {}", e))?;

    let event = find_event(&abi, event_sig)?;
    decoder::decode_log(&event, topics, data)
}

fn find_function(abi: &Value, name_or_sig: &str) -> Result<Value, String> {
    let arr = abi.as_array()
        .ok_or("ABI must be an array".to_string())?;

    // Get all functions
    let functions: Vec<&Value> = arr.iter()
        .filter(|item| {
            let typ = item.get("type")
                .and_then(|t| t.as_str())
                .unwrap_or("function");
            typ == "function"
        })
        .collect();

    // Check if it looks like a signature
    if name_or_sig.contains('(') {
        let (name, param_types) = parse_signature(name_or_sig)?;

        for func in functions {
            if func.get("name")
                .and_then(|n| n.as_str())
                .map(|n| n == name)
                .unwrap_or(false)
            {
                let empty_vec = vec![];
                let inputs = func.get("inputs")
                    .and_then(|i| i.as_array())
                    .unwrap_or(&empty_vec);

                let func_param_types: Vec<String> = inputs.iter()
                    .filter_map(|p| p.get("type").and_then(|t| t.as_str()).map(|s| s.to_string()))
                    .collect();

                if func_param_types == param_types {
                    return Ok(func.clone());
                }
            }
        }
        return Err(format!("invalid function signature `{}`", name_or_sig));
    } else {
        // Find by name
        let matching: Vec<&Value> = functions.iter()
            .filter(|f| f.get("name")
                .and_then(|n| n.as_str())
                .map(|n| n == name_or_sig)
                .unwrap_or(false))
            .copied()
            .collect();

        if matching.is_empty() {
            return Err(format!("Function `{}` not found", name_or_sig));
        } else if matching.len() > 1 {
            return Err(format!("More than one function found for name `{}`, try providing the full signature", name_or_sig));
        } else {
            return Ok(matching[0].clone());
        }
    }
}

fn find_event(abi: &Value, name_or_sig: &str) -> Result<Value, String> {
    let arr = abi.as_array()
        .ok_or("ABI must be an array".to_string())?;

    // Get all events
    let events: Vec<&Value> = arr.iter()
        .filter(|item| {
            let typ = item.get("type")
                .and_then(|t| t.as_str())
                .unwrap_or("");
            typ == "event"
        })
        .collect();

    // Check if it looks like a signature
    if name_or_sig.contains('(') {
        let (name, param_types) = parse_signature(name_or_sig)?;

        for evt in events {
            if evt.get("name")
                .and_then(|n| n.as_str())
                .map(|n| n == name)
                .unwrap_or(false)
            {
                let empty_vec = vec![];
                let inputs = evt.get("inputs")
                    .and_then(|i| i.as_array())
                    .unwrap_or(&empty_vec);

                let evt_param_types: Vec<String> = inputs.iter()
                    .filter_map(|p| p.get("type").and_then(|t| t.as_str()).map(|s| s.to_string()))
                    .collect();

                if evt_param_types == param_types {
                    return Ok(evt.clone());
                }
            }
        }
        return Err(format!("invalid event signature `{}`", name_or_sig));
    } else {
        // Find by name
        let matching: Vec<&Value> = events.iter()
            .filter(|e| e.get("name")
                .and_then(|n| n.as_str())
                .map(|n| n == name_or_sig)
                .unwrap_or(false))
            .copied()
            .collect();

        if matching.is_empty() {
            return Err(format!("Event `{}` not found", name_or_sig));
        } else if matching.len() > 1 {
            return Err(format!("More than one event found for name `{}`, try providing the full signature", name_or_sig));
        } else {
            return Ok(matching[0].clone());
        }
    }
}

fn parse_signature(sig: &str) -> Result<(String, Vec<String>), String> {
    if !sig.contains('(') || !sig.contains(')') {
        return Err(format!("Invalid signature format: {}", sig));
    }

    let paren_idx = sig.find('(').unwrap();
    let name = sig[..paren_idx].to_string();

    let closing_paren = sig.rfind(')').unwrap();
    let params_str = &sig[paren_idx + 1..closing_paren];

    let types = if params_str.is_empty() {
        vec![]
    } else {
        params_str.split(',')
            .map(|s| s.trim().to_string())
            .collect()
    };

    Ok((name, types))
}

pub fn compute_function_selector(func: &Value) -> Result<Vec<u8>, String> {
    let name = func.get("name")
        .and_then(|n| n.as_str())
        .ok_or("Function must have a name")?;

    let empty_vec = vec![];
    let inputs = func.get("inputs")
        .and_then(|i| i.as_array())
        .unwrap_or(&empty_vec);

    let mut signature = format!("{}(", name);

    let types: Vec<String> = inputs.iter()
        .filter_map(|p| p.get("type").and_then(|t| t.as_str()).map(|s| s.to_string()))
        .collect();

    signature.push_str(&types.join(","));
    signature.push(')');

    let hash = keccak256(signature.as_bytes());
    Ok(hash[..4].to_vec())
}

pub fn keccak256(data: &[u8]) -> Vec<u8> {
    // Implement Keccak256
    keccak_impl(data)
}

fn keccak_impl(data: &[u8]) -> Vec<u8> {
    let mut state = [0u64; 25];
    let rate = 136; // 1088 bits / 8 = 136 bytes

    // Absorb phase
    for (i, chunk) in data.chunks(rate).enumerate() {
        for (j, &byte) in chunk.iter().enumerate() {
            let offset = i * rate + j;
            let word_idx = (offset / 8) % 25;
            let byte_idx = offset % 8;
            state[word_idx] ^= (byte as u64) << (byte_idx * 8);
        }
        keccak_f(&mut state);
    }

    // Padding
    let last_block_pos = data.len() % rate;
