pub fn keccak256(data: &[u8]) -> Vec<u8> {
    // Keccak-256 implementation using linear state layout
    let mut state = [0u64; 25];
    let rate_bytes = 136; // 1088 bits = 136 bytes for SHA3-256

    // Absorb phase
    for chunk in data.chunks(rate_bytes) {
        for (i, &byte) in chunk.iter().enumerate() {
            let lane = i / 8;
            let offset = (i % 8) * 8;
            state[lane] ^= (byte as u64) << offset;
        }
        keccak_f(&mut state);
    }

    // Padding
    let last_pos = data.len() % rate_bytes;
    let mut final_block = vec![0u8; rate_bytes];
    final_block[last_pos] = 0x01;
    final_block[rate_bytes - 1] |= 0x80;

    for (i, &byte) in final_block.iter().enumerate() {
        let lane = i / 8;
        let offset = (i % 8) * 8;
        state[lane] ^= (byte as u64) << offset;
    }
    keccak_f(&mut state);

    // Squeeze phase
    let mut result = vec![];
    for i in 0..4 {
        let word = state[i];
        for j in 0..8 {
            result.push(((word >> (j * 8)) & 0xFF) as u8);
        }
    }
    result
}

fn keccak_f(state: &mut [u64; 25]) {
    for round in 0..24 {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[index(x, 0)] ^ state[index(x, 1)] ^ state[index(x, 2)] ^ state[index(x, 3)] ^ state[index(x, 4)];
