fn keccak_f(state: &mut [u64; 25]) {
    for round in 0..24 {
        // Theta
        let c0 = state[0] ^ state[5] ^ state[10] ^ state[15] ^ state[20];
        let c1 = state[1] ^ state[6] ^ state[11] ^ state[16] ^ state[21];
        let c2 = state[2] ^ state[7] ^ state[12] ^ state[17] ^ state[22];
        let c3 = state[3] ^ state[8] ^ state[13] ^ state[18] ^ state[23];
        let c4 = state[4] ^ state[9] ^ state[14] ^ state[19] ^ state[24];

        let d0 = c4 ^ ((c1 << 1) | (c1 >> 63));
        let d1 = c0 ^ ((c2 << 1) | (c2 >> 63));
        let d2 = c1 ^ ((c3 << 1) | (c3 >> 63));
        let d3 = c2 ^ ((c4 << 1) | (c4 >> 63));
        let d4 = c3 ^ ((c0 << 1) | (c0 >> 63));

        for i in 0..5 {
            state[i] ^= d0;
            state[i + 5] ^= d1;
            state[i + 10] ^= d2;
            state[i + 15] ^= d3;
            state[i + 20] ^= d4;
        }

        // Rho and Pi
        let mut b = [0u64; 25];
        let rho = [0, 1, 62, 28, 27, 36, 44, 55, 20, 3, 10, 43, 25, 39, 41, 45, 2, 14, 61, 56, 21, 8, 18, 2, 50];
        let pi = [0, 10, 20, 5, 15, 16, 1, 11, 21, 6, 7, 17, 2, 12, 22, 23, 8, 18, 3, 13, 14, 4, 9, 19, 24];

        for i in 0..25 {
            let r = rho[i];
            b[pi[i]] = if r == 0 { state[i] } else { (state[i] << r) | (state[i] >> (64 - r)) };
        }

        // Chi
        for i in 0..5 {
            for j in 0..5 {
                let idx = i + 5 * j;
                state[idx] = b[idx] ^ ((!b[((i + 1) % 5) + 5 * j]) & b[((i + 2) % 5) + 5 * j]);
            }
        }

        // Iota
        state[0] ^= RC[round];
    }
}

fn hex_to_vec(s: &str) -> Vec<u8> {
    let mut result = vec![];
    for i in (0..s.len()).step_by(2) {
        if i + 1 < s.len() {
            let byte_str = &s[i..i+2];
            if let Ok(b) = u8::from_str_radix(byte_str, 16) {
                result.push(b);
            }
        }
    }
    result
}

const RC: [u64; 24] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a, 0x8000000080008000,
    0x000000008000800a, 0x000000008000000b, 0x0000000000000001, 0x000000008000008b,
    0x0000000080008089, 0x000000008000008a, 0x000000000000008b, 0x0000000000008009,
